query CustomerRetentionState {
  customers(first: 10) {
    nodes {
      id
      numberOfOrders
      amountSpent {
        amount
        currencyCode
      }
      state
      emailMarketingConsent {
        marketingState
      }
    }
    pageInfo {
      hasNextPage
    }
  }
  segments(first: 50) {
    nodes {
      id
      name
      query
    }
  }
}

