query ActiveProvenProducts {
  products(first: 50, query: "status:ACTIVE") {
    nodes {
      id
      title
      status
      totalInventory
      variants(first: 20) {
        nodes {
          id
          price
          inventoryQuantity
        }
      }
    }
  }
}

